import{_ as p,a0 as r,w as l,s as d,I as o,x as n,a1 as i,A as s,ao as h}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在 Antergos Linux 中使用 iPhone | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Antergos Linux 中使用 iPhone | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Antergos Linux 中使用 iPhone | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Antergos Linux 中使用 iPhone | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151012 How To Use iPhone In Antergos Linux","title":"如何在 Antergos Linux 中使用 iPhone","tag":"201511","desc":""},"relativePath":"201511/20151012 How To Use iPhone In Antergos Linux.md","filePath":"[post].md"}'),u={name:"201511/20151012 How To Use iPhone In Antergos Linux.md"};function a(g,e,P,m,x,f){const t=r("Link");return l(),d("div",null,[e[20]||(e[20]=o("h1",{id:"如何在-antergos-linux-中使用-iphone",tabindex:"-1"},[n("如何在 Antergos Linux 中使用 iPhone "),o("a",{class:"header-anchor",href:"#如何在-antergos-linux-中使用-iphone","aria-label":"Permalink to “如何在 Antergos Linux 中使用 iPhone”"},"​")],-1)),e[21]||(e[21]=o("p",null,[o("img",{src:"http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/10/iPhone-Antergos-Arch-Linux.jpg",alt:""})],-1)),e[22]||(e[22]=o("p",null,"在Arch Linux中使用iPhone遇到麻烦了么？iPhone和Linux从来都没有很好地集成。本教程中，我会向你展示如何在Antergos Linux中使用iPhone，对于同样基于Arch的的Linux发行版如Manjaro也应该同样管用。",-1)),o("p",null,[e[2]||(e[2]=n("我最近购买了一台全新的iPhone 6S，当我连接到Antergos Linux中要拷贝一些照片时，它完全没有检测到它。我看见iPhone正在被充电并且我已经允许了iPhone“信任这台电脑”，但是还是完全没有检测到。我尝试运行",-1)),e[3]||(e[3]=o("code",null,"dmseg",-1)),e[4]||(e[4]=n("但是没有关于iPhone或者Apple的信息。有趣的是我当我安装好了",-1)),i(t,{href:"http://www.libimobiledevice.org/"},{default:s(()=>[...e[0]||(e[0]=[n("libimobiledevice",-1)])]),_:1}),e[5]||(e[5]=n("，这个就可以解决",-1)),i(t,{href:"http://itsfoss.com/mount-iphone-ipad-ios-7-ubuntu-13-10/"},{default:s(()=>[...e[1]||(e[1]=[n("iPhone在Ubuntu中的挂载问题",-1)])]),_:1}),e[6]||(e[6]=n("。",-1))]),e[23]||(e[23]=h(`<p>我会向你展示如何在Antergos中使用运行iOS 9的iPhone 6S。这会有更多的命令行，但是我假设你用的是ArchLinux，并不惧怕使用终端（也不应该惧怕）。</p><h3 id="在arch-linux中挂载iphone" tabindex="-1">在Arch Linux中挂载iPhone <a class="header-anchor" href="#在arch-linux中挂载iphone" aria-label="Permalink to “在Arch Linux中挂载iPhone”">​</a></h3><p><strong>第一步</strong>：如果已经插入，请拔下你的iPhone。</p><p><strong>第二步</strong>：现在，打开终端输入下面的命令来安装必要的包。如果它们已经安装过了也没有关系。</p><pre><code>sudo pacman -Sy ifuse usbmuxd libplist libimobiledevice
</code></pre><p><strong>第三步</strong>： 这些库和程序安装完成后，重启系统。</p><pre><code>sudo reboot
</code></pre><p><strong>第四步</strong>：创建一个iPhone的挂载目录，我建议在家目录中创建一个iPhone目录。</p><pre><code>mkdir ~/iPhone
</code></pre><p><strong>第五步</strong>：解锁你的手机并插入，如果询问是否信任该计算机，请允许信任。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/10/iPhone-mount-Antergos-Linux-2.jpeg" alt=""></p><p><strong>第六步</strong>： 看看这时iPhone是否已经被机器识别了。</p><pre><code>dmesg | grep -i iphone
</code></pre><p>这时就该显示iPhone和Apple的结果了。就像这样：</p><pre><code>[ 31.003392] ipheth 2-1:4.2: Apple iPhone USB Ethernet device attached
[ 40.950883] ipheth 2-1:4.2: Apple iPhone USB Ethernet now disconnected
[ 47.471897] ipheth 2-1:4.2: Apple iPhone USB Ethernet device attached
[ 82.967116] ipheth 2-1:4.2: Apple iPhone USB Ethernet now disconnected
[ 106.735932] ipheth 2-1:4.2: Apple iPhone USB Ethernet device attached
</code></pre><p>这意味着这时iPhone已经被Antergos/Arch成功地识别了。</p><p><strong>第七步</strong>: 设置完成后是时候挂载iPhone了，使用下面的命令：</p><pre><code>ifuse ~/iPhone
</code></pre><p>由于我们在家目录中创建了挂载目录，你不需要root权限就可以在家目录中看见。如果命令成功了，你就不会看见任何输出。</p><p>回到Files看下iPhone是否已经识别。对于我而言，在Antergos中看上去这样：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/10/iPhone-mount-Antergos-Linux.jpeg" alt=""></p><p>你可以在这个目录中访问文件。从这里复制文件或者复制到里面。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/10/iPhone-mount-Antergos-Linux-1.jpeg" alt=""></p><p><strong>第八步</strong>： 当你想要卸载的时候，使用这个命令：</p><pre><code>sudo umount ~/iPhone
</code></pre><h3 id="对你有用么" tabindex="-1">对你有用么？ <a class="header-anchor" href="#对你有用么" aria-label="Permalink to “对你有用么？”">​</a></h3><p>我知道这并不是非常方便和理想，iPhone应该像其他USB设备那样工作，但是事情并不总是像人们想的那样。好的是一点小的DIY就能解决这个问题带来了一点成就感（至少对我而言）。我必须要说的是Antergos应该修复这个问题让iPhone可以默认挂载。</p><p>这个技巧对你有用么?如果你有任何问题或者建议，欢迎留下评论。</p><hr>`,29)),o("p",null,[e[8]||(e[8]=n("via: ",-1)),i(t,{href:"http://itsfoss.com/iphone-antergos-linux/"},{default:s(()=>[...e[7]||(e[7]=[n("http://itsfoss.com/iphone-antergos-linux/",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=n("作者：",-1)),i(t,{href:"http://itsfoss.com/author/abhishek/"},{default:s(()=>[...e[9]||(e[9]=[n("Abhishek",-1)])]),_:1}),e[13]||(e[13]=n(" 译者：",-1)),i(t,{href:"https://github.com/geekpi"},{default:s(()=>[...e[10]||(e[10]=[n("geekpi",-1)])]),_:1}),e[14]||(e[14]=n(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[11]||(e[11]=[n("wxy",-1)])]),_:1})]),o("p",null,[e[17]||(e[17]=n("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[15]||(e[15]=[n("LCTT",-1)])]),_:1}),e[18]||(e[18]=n(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:s(()=>[...e[16]||(e[16]=[n("Linux中国",-1)])]),_:1}),e[19]||(e[19]=n(" 荣誉推出",-1))])])}const b=p(u,[["render",a]]);export{T as __pageData,b as default};
